//! Generated byte fields are explicit test oracles, never production layouts.
use reversebolt_core::{
    Result,
    coverage::{CHUNK_BYTES, Region},
    discovery::Kind,
    live::{CaptureMode, LiveSession, NativeTarget, NumberTrack, ProcessInfo, Screen},
    memory_evidence::{Archive, Export, Manifest},
    memory_trajectories::{self as m, Report, Verdict},
    visual,
};
use std::{
    cell::Cell,
    collections::BTreeSet,
    fs,
    path::{Path, PathBuf},
    rc::Rc,
};

const BASE: u64 = 0x10000;
struct Fixture {
    info: ProcessInfo,
    frames: Vec<Vec<u8>>,
    frame: Rc<Cell<usize>>,
    missing: BTreeSet<(usize, u64)>,
}
impl NativeTarget for Fixture {
    fn info(&self) -> &ProcessInfo {
        &self.info
    }
    fn alive(&self) -> bool {
        true
    }
    fn regions(&self) -> Result<Vec<Region>> {
        Ok(vec![Region {
            base: BASE,
            length: self.frames[0].len(),
            image: false,
            allocation_base: BASE,
            protection: 4,
            kind: 0x20000,
        }])
    }
    fn read(&self, address: u64, length: usize) -> Result<Vec<u8>> {
        if self.missing.contains(&(self.frame.get(), address)) {
            return Err("Generated unavailable read".into());
        }
        let offset = (address - BASE) as usize;
        Ok(self.frames[self.frame.get()][offset..offset + length].to_vec())
    }
    fn screen(&self, _: &Path) -> Result<Screen> {
        Err("This fixture supplies no image".into())
    }
}

fn recording(
    frames: Vec<Vec<u8>>,
    missing: BTreeSet<(usize, u64)>,
    label: &str,
) -> (Export, Archive) {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../target/memory-trajectory-tests")
        .join(uuid::Uuid::new_v4().to_string());
    let count = frames.len();
    let frame = Rc::new(Cell::new(0));
    let target = Fixture {
        info: ProcessInfo {
            name: label.into(),
            ..Default::default()
        },
        frames,
        frame: frame.clone(),
        missing,
    };
    let mut session = LiveSession::attach(Box::new(target), 4, path).unwrap();
    for i in 0..count {
        frame.set(i);
        if i == 3 {
            session.capture_mode(CaptureMode::Play).unwrap();
        }
        session.capture().unwrap();
    }
    session.view.tracks = vec![NumberTrack {
        id: 7,
        label: label.into(),
        bounds: [1.; 4],
        samples: vec![Some(label.len() as f64); count + 1],
        matches: vec![],
        readings: vec![],
        active: true,
    }];
    let e = session
        .export_memory_evidence(&session.view.investigation_id, 1, count + 1)
        .unwrap();
    drop(session);
    let archive = Archive::open(Path::new(&e.directory), &e.manifest_sha256).unwrap();
    (e, archive)
}

fn fields() -> Vec<Vec<u8>> {
    (0..12)
        .map(|i| {
            let mut bytes = vec![0; 2 * CHUNK_BYTES];
            let toggle = if i % 4 < 2 { 10i32 } else { 30 };
            let triangle = [0., 2., 5., 2., 0., 3., 5., 3., 0., 2., 5., 1.][i];
            bytes[0..4].copy_from_slice(&toggle.to_le_bytes());
            bytes[8..12].copy_from_slice(&(i as f32 * 0.25 + 2.).to_le_bytes());
            bytes[16..24].copy_from_slice(&f64::to_le_bytes(triangle));
            bytes[24..28].copy_from_slice(&(-toggle * 3 + 200).to_le_bytes());
            bytes[32..36].copy_from_slice(&(i as i32 + 1000).to_le_bytes());
            bytes[40..44].copy_from_slice(&(if i < 6 { toggle } else { 99 }).to_le_bytes());
            bytes[48..52].copy_from_slice(&88i32.to_le_bytes());
            bytes[56..60].copy_from_slice(&f32::NAN.to_le_bytes());
            bytes[64..68].copy_from_slice(&(if i < 6 { 0 } else { i as i32 }).to_le_bytes());
            bytes[CHUNK_BYTES..CHUNK_BYTES + 4].copy_from_slice(&(i as i32 * 10).to_le_bytes());
            bytes
        })
        .collect()
}

fn member(report: &Report, offset: usize, kind: Kind) -> &m::Member {
    report
        .groups
        .iter()
        .flat_map(|g| &g.members)
        .find(|m| m.selection.address == BASE + offset as u64 && m.selection.kind == kind)
        .unwrap()
}
fn selected(report: &Report) -> serde_json::Value {
    serde_json::json!({"coverage":report.coverage,"groups":report.groups.iter().map(|g|serde_json::json!({"signature":g.order_signature,"count":g.candidate_count,"members":g.members.iter().map(|m|&m.selection).collect::<Vec<_>>()})).collect::<Vec<_>>()})
}

#[test]
fn blind_selection_keeps_type_rivals_and_detects_later_pattern_violations() {
    let (export, archive) = recording(fields(), BTreeSet::new(), "invented screen number");
    let report = m::analyze(&archive).unwrap();
    assert_eq!(report.selection_captures, vec![1, 2, 3, 5, 6, 7]);
    assert_eq!(report.assessment_captures, vec![8, 9, 10, 11, 12, 13]);
    assert_eq!(
        member(&report, 0, Kind::I32).assessment.verdict,
        Verdict::Consistent
    );
    assert_eq!(
        member(&report, 8, Kind::F32).assessment.verdict,
        Verdict::Consistent
    );
    assert_eq!(
        member(&report, 8, Kind::I32).assessment.verdict,
        Verdict::Consistent
    ); // ambiguous encoding survives
    assert_eq!(
        member(&report, 16, Kind::F64).assessment.verdict,
        Verdict::NotPredicted
    );
    assert_eq!(
        member(&report, 40, Kind::I32).assessment.verdict,
        Verdict::Contradicted
    );
    assert!(
        !report
            .groups
            .iter()
            .flat_map(|g| &g.members)
            .any(|m| m.selection.address == BASE + 48 || m.selection.address == BASE + 64)
    );
    let group = |offset| {
        report
            .groups
            .iter()
            .position(|g| {
                g.members
                    .iter()
                    .any(|m| m.selection.address == BASE + offset && m.selection.kind == Kind::I32)
            })
            .unwrap()
    };
    assert_eq!(group(0), group(24)); // opposite affine copy; not evidence of shared control
    assert_eq!(group(0), group(40)); // later contradiction stays in original selection
    assert_eq!(report.coverage.omitted_groups, 0);
    let output = Path::new(&export.directory).join("trajectory-report.json");
    fs::write(&output, serde_json::to_vec_pretty(&report).unwrap()).unwrap();
    println!(
        "MEMORY_TRAJECTORIES_FIXTURE={}",
        serde_json::to_string(&export).unwrap()
    );
}

#[test]
fn future_bytes_missing_reads_and_labels_cannot_change_prefix_selection() {
    let (_, a) = recording(fields(), BTreeSet::new(), "Health 100");
    let first = m::analyze(&a).unwrap();
    let mut changed = fields();
    for (i, bytes) in changed.iter_mut().enumerate().skip(6) {
        bytes[8..12].copy_from_slice(&f32::NAN.to_le_bytes());
        bytes[32..36].copy_from_slice(&(1000 - i as i32).to_le_bytes());
        bytes[40..44].copy_from_slice(&(if i % 4 < 2 { 10i32 } else { 30 }).to_le_bytes());
    }
    let missing = (6..12).map(|i| (i, BASE + CHUNK_BYTES as u64)).collect();
    let (_, b) = recording(changed, missing, "Totally different screen label 999999");
    let second = m::analyze(&b).unwrap();
    assert_eq!(selected(&first), selected(&second));
    assert_eq!(member(&second, 8, Kind::F32).assessment.invalid_numbers, 6);
    assert_eq!(
        member(&second, 8, Kind::F32).assessment.verdict,
        Verdict::Insufficient
    );
    assert_eq!(
        member(&second, 32, Kind::I32).assessment.verdict,
        Verdict::Contradicted
    );
    assert_eq!(
        member(&second, 40, Kind::I32).assessment.verdict,
        Verdict::Consistent
    );
    assert_eq!(
        member(&second, CHUNK_BYTES, Kind::I32)
            .assessment
            .missing_reads,
        6
    );
    assert_eq!(
        member(&second, CHUNK_BYTES, Kind::I32).assessment.verdict,
        Verdict::Insufficient
    );
}

fn changed_manifest(export: &Export, change: impl FnOnce(&mut Manifest)) -> (PathBuf, Archive) {
    let old = Path::new(&export.directory);
    let path = old.parent().unwrap().join(uuid::Uuid::new_v4().to_string());
    fs::create_dir(&path).unwrap();
    fs::copy(old.join("bytes.bin"), path.join("bytes.bin")).unwrap();
    let mut manifest: Manifest =
        serde_json::from_slice(&fs::read(old.join("manifest.json")).unwrap()).unwrap();
    change(&mut manifest);
    let bytes = serde_json::to_vec(&manifest).unwrap();
    let hash = visual::digest(&bytes);
    fs::write(path.join("manifest.json"), bytes).unwrap();
    let archive = Archive::open(&path, &hash).unwrap();
    (path, archive)
}

#[test]
fn final_mapping_flags_and_chunk_order_do_not_leak_into_selection() {
    let (export, a) = recording(fields(), BTreeSet::new(), "unused");
    let original = m::analyze(&a).unwrap();
    let (_, b) = changed_manifest(&export, |m| {
        m.plan.reverse();
        m.invalid_chunks = vec![BASE];
    });
    let changed = m::analyze(&b).unwrap();
    assert_eq!(selected(&original), selected(&changed));
    assert!(member(&changed, 0, Kind::I32).chunk_invalidated_in_recording);
}

#[test]
fn missing_prefix_excludes_chunk_but_stream_verifies_its_later_bytes() {
    let (export, a) = recording(
        fields(),
        BTreeSet::from([(2, BASE + CHUNK_BYTES as u64)]),
        "unused",
    );
    let report = m::analyze(&a).unwrap();
    assert_eq!(report.coverage.missing_prefix_bytes, CHUNK_BYTES);
    assert_eq!(report.coverage.complete_prefix_bytes, CHUNK_BYTES);
    assert!(
        report
            .groups
            .iter()
            .flat_map(|g| &g.members)
            .all(|m| m.selection.address < BASE + CHUNK_BYTES as u64)
    );
    let path = Path::new(&export.directory).join("bytes.bin");
    let mut bytes = fs::read(&path).unwrap();
    *bytes.last_mut().unwrap() ^= 1;
    fs::write(path, bytes).unwrap();
    assert!(m::analyze(&a).unwrap_err().contains("checksum"));
}

#[test]
fn bounded_selection_reports_omissions_in_noisy_memory_and_is_deterministic() {
    let mut frames = fields();
    let mut random = 0x45ab78d9u32;
    for bytes in &mut frames {
        for word in bytes[128..].as_chunks_mut::<4>().0 {
            random ^= random << 13;
            random ^= random >> 17;
            random ^= random << 5;
            word.copy_from_slice(&random.to_le_bytes());
        }
    }
    let (export, a) = recording(frames, BTreeSet::new(), "noise fixture");
    let started = std::time::Instant::now();
    let report = m::analyze(&a).unwrap();
    let elapsed = started.elapsed().as_millis();
    assert_eq!(report.groups.len(), m::MAX_GROUPS);
    assert!(
        report
            .groups
            .iter()
            .all(|g| g.members.len() <= m::MAX_MEMBERS)
    );
    assert!(report.coverage.omitted_groups > 0);
    assert!(report.coverage.omitted_candidates > 0);
    assert!(
        report
            .groups
            .iter()
            .all(|g| [Kind::I32, Kind::F32, Kind::F64].iter().all(|kind| g
                .members
                .iter()
                .filter(|m| m.selection.kind == *kind)
                .count()
                <= m::MAX_PER_KIND))
    );
    assert_eq!(
        member(&report, 8, Kind::F32).assessment.verdict,
        Verdict::Consistent
    );
    assert_eq!(
        member(&report, 0, Kind::I32).assessment.verdict,
        Verdict::Consistent
    );
    let (_, b) = changed_manifest(&export, |m| m.plan.reverse());
    assert_eq!(selected(&report), selected(&m::analyze(&b).unwrap()));
    println!(
        "MEMORY_TRAJECTORIES_NOISE={}",
        serde_json::json!({"export":export,"elapsed_ms":elapsed,"coverage":report.coverage,"known_toggle_retained":true})
    );
}

#[test]
fn short_and_static_recordings_do_not_invent_candidates() {
    let (_, short) = recording(fields()[..8].to_vec(), BTreeSet::new(), "unused");
    assert!(m::analyze(&short).is_err());
    let (_, a) = recording(
        vec![vec![0; CHUNK_BYTES]; 12],
        BTreeSet::new(),
        "Health 100",
    );
    let report = m::analyze(&a).unwrap();
    assert!(report.groups.is_empty());
    assert_eq!(report.coverage.qualifying_candidates, 0);
}

#[test]
fn analysis_and_verification_cancel_between_bounded_chunks() {
    let (_, archive) = recording(fields(), BTreeSet::new(), "unused");
    let checks = Cell::new(0);
    let error = m::analyze_with_cancel(&archive, || {
        checks.set(checks.get() + 1);
        checks.get() >= 3
    })
    .unwrap_err();
    assert!(error.contains("cancelled"));
    assert_eq!(checks.get(), 3);
    let checks = Cell::new(0);
    assert!(
        archive
            .verify_with_cancel(|| {
                checks.set(checks.get() + 1);
                checks.get() >= 2
            })
            .unwrap_err()
            .contains("cancelled")
    );
    assert_eq!(checks.get(), 2);
}

#[test]
fn proposal_store_recovers_identical_publication_and_rejects_changed_or_oversized_files() {
    use m::store;
    let (export, archive) = recording(fields(), BTreeSet::new(), "unused");
    let root = Path::new(&export.directory).join("proposal-store-test");
    let report = m::analyze(&archive).unwrap();
    let summary = store::save(&root, &report, report.capture_count).unwrap();
    let folder = root
        .join("memory-proposals")
        .join(&report.investigation_id)
        .join("batch-001");
    let original = fs::read(folder.join("report.json")).unwrap();
    let summary_bytes = fs::read(folder.join("summary.json")).unwrap();
    assert!(store::save(&root, &report, report.capture_count + 1).is_err());
    fs::remove_file(folder.join("summary.json")).unwrap();
    assert!(
        store::load_summary(&root, &report.investigation_id, 1)
            .unwrap()
            .is_none()
    );
    assert_eq!(
        store::save(&root, &report, report.capture_count)
            .unwrap()
            .report_sha256,
        summary.report_sha256
    );
    let mut changed = report.clone();
    changed.groups[0].members[0].selection.values[0] += 1.;
    assert!(store::save(&root, &changed, report.capture_count).is_err());
    assert_eq!(fs::read(folder.join("report.json")).unwrap(), original);
    let mut changed_summary = summary.clone();
    changed_summary.captures += 1;
    fs::write(
        folder.join("summary.json"),
        serde_json::to_vec(&changed_summary).unwrap(),
    )
    .unwrap();
    assert!(store::load_summary(&root, &report.investigation_id, 1).is_err());
    fs::write(folder.join("summary.json"), summary_bytes).unwrap();
    assert!(
        store::page(
            &root,
            &report.investigation_id,
            1,
            &summary.report_sha256,
            usize::MAX,
            8
        )
        .is_err()
    );
    let file = fs::OpenOptions::new()
        .write(true)
        .open(folder.join("report.json"))
        .unwrap();
    file.set_len(store::MAX_REPORT_BYTES as u64 + 1).unwrap();
    assert!(
        store::read(&root, &report.investigation_id, 1, &summary.report_sha256)
            .unwrap_err()
            .contains("limit")
    );
}

#[test]
fn missing_sample_does_not_bridge_a_monotonicity_check() {
    let mut frames = fields();
    for (i, bytes) in frames.iter_mut().enumerate().skip(7) {
        bytes[CHUNK_BYTES..CHUNK_BYTES + 4].copy_from_slice(&(i as i32 - 7).to_le_bytes());
    }
    let (_, a) = recording(
        frames,
        BTreeSet::from([(6, BASE + CHUNK_BYTES as u64)]),
        "unused",
    );
    let report = m::analyze(&a).unwrap();
    let result = &member(&report, CHUNK_BYTES, Kind::I32).assessment;
    assert_eq!(result.missing_reads, 1);
    assert_eq!(result.checked, 4);
    assert_eq!(result.violations, 0);
    assert_eq!(result.verdict, Verdict::Consistent);
}

#[test]
fn generated_multi_seed_recovery_measurement_keeps_failures_visible() {
    let planted = [
        (0, Kind::I32),
        (8, Kind::F32),
        (16, Kind::F64),
        (24, Kind::I32),
        (32, Kind::I32),
        (40, Kind::I32),
    ];
    let mut measurements = vec![];
    for seed in 1..=12u32 {
        let mut frames = fields();
        let mut random = seed.wrapping_mul(0x45ab78d9);
        for bytes in &mut frames {
            for word in bytes[128..].as_chunks_mut::<4>().0 {
                random ^= random << 13;
                random ^= random >> 17;
                random ^= random << 5;
                word.copy_from_slice(&random.to_le_bytes());
            }
        }
        let (export, a) = recording(frames, BTreeSet::new(), &format!("generated seed {seed}"));
        let started = std::time::Instant::now();
        let report = m::analyze(&a).unwrap();
        let elapsed = started.elapsed().as_millis();
        let members: Vec<_> = report.groups.iter().flat_map(|g| &g.members).collect();
        assert!(
            report.groups.len() <= m::MAX_GROUPS && members.len() <= m::MAX_GROUPS * m::MAX_MEMBERS
        );
        let recovered:Vec<_>=planted.iter().map(|(offset,kind)| {
            let found=members.iter().find(|m|m.selection.address==BASE+*offset && m.selection.kind==*kind);
            serde_json::json!({"offset":offset,"kind":kind,"retained":found.is_some(),"assessment":found.map(|m|m.assessment.verdict)})
        }).collect();
        measurements.push(serde_json::json!({"seed":seed,"export":export,"elapsed_ms":elapsed,"coverage":report.coverage,"planted":recovered,
            "consistent_members":members.iter().filter(|m|m.assessment.verdict==Verdict::Consistent).count(),
            "contradicted_members":members.iter().filter(|m|m.assessment.verdict==Verdict::Contradicted).count(),
            "not_predicted_members":members.iter().filter(|m|m.assessment.verdict==Verdict::NotPredicted).count()}));
    }
    // This is a measurement, not a test claiming all planted fields are found.
    println!(
        "MEMORY_TRAJECTORIES_MEASUREMENT={}",
        serde_json::to_string(&measurements).unwrap()
    );
}
